export class UserId {
  value: string;

  constructor(value: string) {
    this.value = value;
    this.ensureIsValid();
  }

  // user_pos.id es bigint GENERATED BY DEFAULT AS IDENTITY: un entero positivo.
  // Se representa como string (no number) para no perder precisión en bigints grandes.
  private ensureIsValid() {
    if (!/^[0-9]+$/.test(this.value)) {
      throw new Error("UserId must be a positive integer (user_pos.id is bigint)");
    }
  }
}
